"""Chart of accounts: paths, types, patterns."""
import re

from .currency import CURRENCIES
from .dates import is_date
from .errors import ConflictError, NotFoundError, ValidationError
from .model import Account


class ChartError(ValidationError):
    pass


class _ChartConflict(ChartError, ConflictError):
    code = "conflict"


ROOT_TYPES = {
    "Assets": "asset",
    "Liabilities": "liability",
    "Equity": "equity",
    "Income": "income",
    "Expenses": "expense",
}
TYPES = tuple(ROOT_TYPES.values())

_SEG_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*")


def valid_path(text):
    if not isinstance(text, str):
        return False
    parts = text.split(":")
    if parts[0] not in ROOT_TYPES:
        return False
    return all(_SEG_RE.fullmatch(p) for p in parts)


def _need_path(path):
    if not valid_path(path):
        raise ChartError("invalid account path '%s'" % (path,))


def parent_path(path):
    _need_path(path)
    head, sep, _ = path.rpartition(":")
    return head if sep else None


def account_type(path):
    _need_path(path)
    return ROOT_TYPES[path.split(":", 1)[0]]


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ChartError("invalid account pattern '%s'" % (pattern,))
    parts = pattern.split(":")
    for p in parts:
        if p not in ("*", "**") and not _SEG_RE.fullmatch(p):
            raise ChartError("invalid account pattern '%s'" % pattern)
    return parts


def _match_segments(pat, segs):
    # pat: list of pattern parts, segs: list of path segments; full match
    if not pat:
        return not segs
    head = pat[0]
    if head == "**":
        for n in range(1, len(segs) + 1):
            if _match_segments(pat[1:], segs[n:]):
                return True
        return False
    if not segs:
        return False
    if head == "*" or head == segs[0]:
        return _match_segments(pat[1:], segs[1:])
    return False


def path_matches(pattern, path):
    parts = _check_pattern(pattern)
    if not isinstance(path, str):
        return False
    if "*" not in pattern:
        return path == pattern or path.startswith(pattern + ":")
    return _match_segments(parts, path.split(":"))


def _sort_key(path):
    return tuple(path.split(":"))


class Chart:
    def __init__(self):
        self._accounts = {}
        self._explicit = set()

    def add(self, path, type=None, currency=None, opened=None, note=""):
        _need_path(path)
        kind = ROOT_TYPES[path.split(":", 1)[0]]
        if type is not None and type != kind:
            if type not in TYPES:
                raise ChartError("unknown account type '%s'" % (type,))
            raise ChartError("account %s is of type %s, not %s" % (path, kind, type))
        if currency is not None and (not isinstance(currency, str) or currency not in CURRENCIES):
            raise ChartError("unknown currency '%s'" % (currency,))
        if opened is not None and not is_date(opened):
            raise ChartError("opened must be a date, got '%s'" % (opened,))
        if not isinstance(note, str):
            raise ChartError("note must be text")
        if path in self._explicit:
            raise _ChartConflict("account %s already exists" % path)
        existing = self._accounts.get(path)
        if existing is not None:
            existing.currency = currency
            existing.opened = opened
            existing.note = note
            self._explicit.add(path)
            return existing
        parts = path.split(":")
        for i in range(1, len(parts)):
            p = ":".join(parts[:i])
            if p not in self._accounts:
                self._accounts[p] = Account(p, ROOT_TYPES[parts[0]])
        acct = Account(path, kind, currency, opened, None, note)
        self._accounts[path] = acct
        self._explicit.add(path)
        return acct

    def get(self, path):
        if not isinstance(path, str) or path not in self._accounts:
            raise NotFoundError("no such account '%s'" % (path,))
        return self._accounts[path]

    def exists(self, path):
        return isinstance(path, str) and path in self._accounts

    __contains__ = exists

    def __len__(self):
        return len(self._accounts)

    def accounts(self):
        return [self._accounts[p] for p in sorted(self._accounts, key=_sort_key)]

    def children(self, path):
        self.get(path)
        n = path.count(":") + 1
        return [a for a in self.accounts() if a.path.startswith(path + ":") and a.path.count(":") == n]

    def descendants(self, path):
        self.get(path)
        return [a for a in self.accounts() if a.path.startswith(path + ":")]

    def is_leaf(self, path):
        return not self.children(path)

    def is_open(self, path, on):
        a = self.get(path)
        if not is_date(on):
            raise ChartError("not a date: '%s'" % (on,))
        return (a.opened is None or a.opened <= on) and (a.closed is None or on <= a.closed)

    def close(self, path, on):
        a = self.get(path)
        if not is_date(on):
            raise ChartError("closing date must be a date, got '%s'" % (on,))
