"""The ledger: validated transactions and balances."""
import re
from collections import defaultdict
from datetime import date

from .accounts import Chart
from .currency import RateTable
from .dates import is_date
from .errors import NotFoundError, ValidationError
from .model import Posting, Transaction
from .money import Money, format_minor


class LedgerError(ValidationError):
    pass


_TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _text(value, what):
    if not isinstance(value, str) or "\n" in value or "\r" in value:
        raise LedgerError("%s must be text without a line break" % what)


class Ledger:
    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._max_id = 0

    def __len__(self):
        return len(self._txs)

    # -- validation -------------------------------------------------------
    def _build(self, tx, tx_id):
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: '%s'" % (tx,))
        if not is_date(tx.date):
            raise LedgerError("transaction date must be a date, got '%s'" % (tx.date,))
        if tx.flag not in ("*", "!"):
            raise LedgerError("flag must be '*' or '!', got '%s'" % (tx.flag,))
        _text(tx.payee, "payee")
        _text(tx.narration, "narration")
        if isinstance(tx.tags, str) or not hasattr(tx.tags, "__iter__"):
            raise LedgerError("tags must be a list of names")
        tags = set()
        for t in tx.tags:
            if not isinstance(t, str) or not _TAG_RE.fullmatch(t):
                raise LedgerError("invalid tag '%s'" % (t,))
            tags.add(t.lower())
        if not isinstance(tx.postings, (list, tuple)):
            raise LedgerError("postings must be a list")
        postings = list(tx.postings)
        for p in postings:
            if not isinstance(p, Posting):
                raise LedgerError("not a posting: '%s'" % (p,))
            _text(p.note, "posting note")
            if p.amount is not None and not isinstance(p.amount, Money):
                raise LedgerError("posting amount must be money or None")
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        for p in postings:
            if not self.chart.exists(p.account):
                raise LedgerError("unknown account '%s'" % p.account)
            if not self.chart.is_open(p.account, tx.date):
                raise LedgerError("account %s is not open on %s" % (p.account, tx.date.isoformat()))
            if p.amount is not None:
                self._check_currency(p)
        blanks = [i for i, p in enumerate(postings) if p.amount is None]
        if len(blanks) > 1:
            raise LedgerError("more than one posting without an amount")
        sums = defaultdict(int)
        for p in postings:
            if p.amount is not None:
                sums[p.amount.currency] += p.amount.minor
        if blanks:
            i = blanks[0]
            off = sorted(c for c, v in sums.items() if v != 0)
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            old = postings[i]
            new = [Posting(old.account, Money(-sums[c], c), old.note) for c in off]
            for p in new:
                self._check_currency(p)
            postings[i : i + 1] = new
            sums = defaultdict(int)
            for p in postings:
                sums[p.amount.currency] += p.amount.minor
        bad = sorted(c for c, v in sums.items() if v != 0)
        if bad:
            raise LedgerError(
                "transaction does not balance: "
                + ", ".join("%s %s" % (c, format_minor(sums[c], c)) for c in bad)
            )
        return Transaction(tx.date, tx.payee, tx.narration, postings, tuple(sorted(tags)), tx.flag, tx_id)

    def _check_currency(self, p):
        want = self.chart.get(p.account).currency
        if want is not None and p.amount.currency != want:
            raise LedgerError(
                "account %s only holds %s, not %s" % (p.account, want, p.amount.currency)
            )

    def _assign_id(self, tx):
        if tx.id is None:
            return self._max_id + 1
        if not _is_int(tx.id) or tx.id < 1:
            raise LedgerError("transaction id must be an integer of at least 1, got '%s'" % (tx.id,))
        if tx.id in self._txs:
            raise LedgerError("transaction %d already exists" % tx.id)
        return tx.id

    # -- mutation ---------------------------------------------------------
    def add(self, tx):
        if isinstance(tx, Transaction):
            tx_id = self._assign_id(tx)
        else:
            tx_id = None
        stored = self._build(tx, tx_id)
        self._txs[stored.id] = stored
        self._max_id = max(self._max_id, stored.id)
        return stored

    def add_many(self, transactions):
        snapshot = (dict(self._txs), self._max_id)
        out = []
        try:
            for tx in transactions:
                out.append(self.add(tx))
        except BaseException:
            self._txs, self._max_id = snapshot
            raise
        return out

    def replace(self, id, tx):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: '%s'" % (tx,))
        if tx.id is not None and tx.id != id:
            raise LedgerError("transaction id %s does not match %s" % (tx.id, id))
        stored = self._build(tx, id)
        self._txs[id] = stored
        return stored

    def remove(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return self._txs.pop(id)

    # -- lookup -----------------------------------------------------------
    def get(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return self._txs[id]

    def transactions(self):
        return sorted(self._txs.values(), key=lambda t: (t.date, t.id))

    def postings(self):
        for tx in self.transactions():
            for p in tx.postings:
                yield tx, p

    # -- balances ---------------------------------------------------------
    def _walk(self, as_of):
        if as_of is not None and not is_date(as_of):
            raise LedgerError("as_of must be a date, got '%s'" % (as_of,))
        for tx, p in self.postings():
            if as_of is None or tx.date <= as_of:
                yield p

    @staticmethod
    def _clean(acc):
        out = {}
        for a, cur in acc.items():
            cur = {c: v for c, v in cur.items() if v != 0}
            if cur:
                out[a] = cur
        return out

    def balances(self, as_of=None):
        acc = defaultdict(lambda: defaultdict(int))
        for p in self._walk(as_of):
            acc[p.account][p.amount.currency] += p.amount.minor
        return self._clean(acc)

    def rollup_balances(self, as_of=None):
        acc = defaultdict(lambda: defaultdict(int))
        for p in self._walk(as_of):
            parts = p.account.split(":")
            for i in range(1, len(parts) + 1):
                acc[":".join(parts[:i])][p.amount.currency] += p.amount.minor
        return self._clean(acc)

    def balance(self, account, as_of=None, currency=None, rollup=True):
        if not self.chart.exists(account):
            raise NotFoundError("no such account '%s'" % (account,))
        sums = defaultdict(int)
        for p in self._walk(as_of):
            if p.account == account or (rollup and p.account.startswith(account + ":")):
                sums[p.amount.currency] += p.amount.minor
        if currency is not None:
            return Money(sums.get(currency, 0), currency)
        return {c: Money(v, c) for c, v in sorted(sums.items()) if v != 0}

