class AuditIdLookupTest(unittest.TestCase):
    def setUp(self):
        self.led = make()
        self.led.add(lunch())

    def test_non_integer_ids_are_not_found(self):
        for bad in (True, 1.0, "1", None, [1], {}, (1,)):
            for name in ("get", "remove"):
                with self.subTest(bad=bad, call=name):
                    with self.assertRaises(NotFoundError) as cm:
                        getattr(self.led, name)(bad)
                    self.assertIn("no transaction", cm.exception.message)
                    self.assertEqual(cm.exception.code, "not_found")
            with self.subTest(bad=bad, call="replace"):
                with self.assertRaises(NotFoundError) as cm:
                    self.led.replace(bad, lunch())
                self.assertIn("no transaction", cm.exception.message)
        self.assertEqual(len(self.led), 1)

    def test_replace_refuses_non_integer_equal_ids(self):
        for bad in (True, 1.0):
            with self.subTest(bad=bad):
                with self.assertRaises(LedgerError):
                    self.led.replace(1, lunch(id=bad))
                self.assertEqual(self.led.get(1).id, 1)
                self.assertIs(type(self.led.get(1).id), int)

    def test_unknown_account_message_with_tuple_account(self):
        for account in (("a", "b"), ["x"], None, 5):
            with self.subTest(account=account):
                tx = T(2024, 3, 1, "x", Posting(account, Money(1, "USD")), P("Assets:Cash", "-0.01 USD"))
                with self.assertRaises(LedgerError) as cm:
                    self.led.add(tx)
                self.assertIn("unknown account", cm.exception.message)


if __name__ == "__main__":
    unittest.main()

